import{_ as a,C as r,o as n,c as i,a2 as t,E as s}from"./chunks/framework.CBxkvBm_.js";const b=JSON.parse('{"title":"Diagram Auto-Layout & Orthogonal Routing","description":"","frontmatter":{},"headers":[],"relativePath":"algorithms/diagram-layout.md","filePath":"algorithms/diagram-layout.md"}'),l={name:"algorithms/diagram-layout.md"};function c(d,e,g,m,p,u){const o=r("MermaidBlock");return n(),i("div",null,[e[0]||(e[0]=t('<h1 id="diagram-auto-layout-orthogonal-routing" tabindex="-1">Diagram Auto-Layout &amp; Orthogonal Routing <a class="header-anchor" href="#diagram-auto-layout-orthogonal-routing" aria-label="Permalink to &quot;Diagram Auto-Layout &amp; Orthogonal Routing&quot;">​</a></h1><p><strong>Implementation</strong>:</p><ul><li>Topology-Shape-Metrics Engine: <code>TsmLayoutEngine</code> in <a href="https://github.com/modelscript/modelscript/tree/main/packages/diagram/src/tsm-layout.ts" target="_blank" rel="noreferrer"><code>packages/diagram/src/tsm-layout.ts</code></a></li><li>Port Constraint &amp; Alignment Solver: <code>PortIlpSolver</code> in <a href="https://github.com/modelscript/modelscript/tree/main/packages/diagram/src/port-ilp-solver.ts" target="_blank" rel="noreferrer"><code>packages/diagram/src/port-ilp-solver.ts</code></a></li><li>Obstacle-Avoiding Channel Router: <code>PortRouter</code> in <a href="https://github.com/modelscript/modelscript/tree/main/packages/diagram/src/port-router.ts" target="_blank" rel="noreferrer"><code>packages/diagram/src/port-router.ts</code></a></li><li>Specialized Engineering Diagram Layouts: <code>synthesizeFaultTreeDiagram</code> (<a href="https://github.com/modelscript/modelscript/tree/main/packages/diagram/src/fault-tree.ts" target="_blank" rel="noreferrer"><code>packages/diagram/src/fault-tree.ts</code></a>), <code>computeSequenceLayout</code> (<a href="https://github.com/modelscript/modelscript/tree/main/packages/diagram/src/sequence-layout.ts" target="_blank" rel="noreferrer"><code>packages/diagram/src/sequence-layout.ts</code></a>), <code>applySwimlaneLayout</code> (<a href="https://github.com/modelscript/modelscript/tree/main/packages/diagram/src/swimlane-layout.ts" target="_blank" rel="noreferrer"><code>packages/diagram/src/swimlane-layout.ts</code></a>), and <code>buildPscadDiagram</code> (<a href="https://github.com/modelscript/modelscript/tree/main/packages/diagram/src/pscad-diagram-builder.ts" target="_blank" rel="noreferrer"><code>packages/diagram/src/pscad-diagram-builder.ts</code></a>)</li><li>Semantic Visual Diffing &amp; Collaborative Presence: <code>buildVisualDiffGraph</code> (<a href="https://github.com/modelscript/modelscript/tree/main/packages/diagram/src/visual-diff-graph.ts" target="_blank" rel="noreferrer"><code>packages/diagram/src/visual-diff-graph.ts</code></a>) and <code>CollabManager</code> (<a href="https://github.com/modelscript/modelscript/tree/main/packages/diagram/src/collab-manager.ts" target="_blank" rel="noreferrer"><code>packages/diagram/src/collab-manager.ts</code></a>)</li></ul><hr><h2 id="academic-citations" tabindex="-1">Academic Citations <a class="header-anchor" href="#academic-citations" aria-label="Permalink to &quot;Academic Citations&quot;">​</a></h2><h3 id="topology-shape-metrics-tsm-kandinsky-orthogonal-layout" tabindex="-1">Topology-Shape-Metrics (TSM / Kandinsky) Orthogonal Layout <a class="header-anchor" href="#topology-shape-metrics-tsm-kandinsky-orthogonal-layout" aria-label="Permalink to &quot;Topology-Shape-Metrics (TSM / Kandinsky) Orthogonal Layout&quot;">​</a></h3><ul><li><strong>Tamassia, R. (1987)</strong>. <em>&quot;On embedding a grid graph with minimum number of bends.&quot;</em><br><strong>SIAM Journal on Computing</strong>, 16(3), pp. 421–444.<br> DOI: <a href="https://doi.org/10.1137/0216030" target="_blank" rel="noreferrer">10.1137/0216030</a></li><li><strong>Fößmeier, U., &amp; Kaufmann, M. (1996)</strong>. <em>&quot;Drawing high-degree graphs with minimum number of bends.&quot;</em><br><strong>Graph Drawing (GD &#39;95)</strong>, Lecture Notes in Computer Science, 1027, pp. 211–225. Springer.<br> DOI: <a href="https://doi.org/10.1007/BFb0021804" target="_blank" rel="noreferrer">10.1007/BFb0021804</a></li><li><strong>Di Battista, G., Eades, P., Tamassia, R., &amp; Tollis, I. G. (1998)</strong>. <em>Graph Drawing: Algorithms for the Visualization of Graphs.</em> Prentice Hall.<br> ISBN: <a href="https://dl.acm.org/doi/book/10.5555/289569" target="_blank" rel="noreferrer">0-13-301615-3</a></li></ul><h3 id="port-constraint-continuous-alignment-ilp" tabindex="-1">Port Constraint &amp; Continuous Alignment ILP <a class="header-anchor" href="#port-constraint-continuous-alignment-ilp" aria-label="Permalink to &quot;Port Constraint &amp; Continuous Alignment ILP&quot;">​</a></h3><ul><li><strong>Spönemann, M., von Hanxleden, R., &amp; Fuhrmann, H. (2014)</strong>. <em>&quot;Port constraints in layout algorithms.&quot;</em><br><strong>Graph Drawing (GD 2014)</strong>, Lecture Notes in Computer Science, 8871, pp. 351–362. Springer.<br> DOI: <a href="https://doi.org/10.1007/978-3-662-45803-7_29" target="_blank" rel="noreferrer">10.1007/978-3-662-45803-7_29</a></li><li><strong>Kieffer, S., Dwyer, T., Marriott, K., &amp; Wybrow, M. (2016)</strong>. <em>&quot;Incremental layout for dynamic schematic diagrams.&quot;</em><br><strong>IEEE Transactions on Visualization and Computer Graphics</strong>, 22(1), pp. 876–885.<br> DOI: <a href="https://doi.org/10.1109/TVCG.2015.2467364" target="_blank" rel="noreferrer">10.1109/TVCG.2015.2467364</a></li><li><strong>Eiglsperger, M., Fößmeier, U., &amp; Kaufmann, M. (2001)</strong>. <em>&quot;Orthogonal graph drawing with constraints.&quot;</em><br><strong>Journal of Graph Algorithms and Applications</strong>, 5(2), pp. 1–24.<br> DOI: <a href="https://doi.org/10.7155/jgaa.00035" target="_blank" rel="noreferrer">10.7155/jgaa.00035</a></li></ul><h3 id="orthogonal-channel-routing-obstacle-avoidance" tabindex="-1">Orthogonal Channel Routing &amp; Obstacle Avoidance <a class="header-anchor" href="#orthogonal-channel-routing-obstacle-avoidance" aria-label="Permalink to &quot;Orthogonal Channel Routing &amp; Obstacle Avoidance&quot;">​</a></h3><ul><li><strong>Lee, C. Y. (1961)</strong>. <em>&quot;An algorithm for path connection and its applications.&quot;</em><br><strong>IRE Transactions on Electronic Computers</strong>, EC-10(3), pp. 346–365.<br> DOI: <a href="https://doi.org/10.1109/TEC.1961.5219222" target="_blank" rel="noreferrer">10.1109/TEC.1961.5219222</a></li><li><strong>Hart, P. E., Nilsson, N. J., &amp; Raphael, B. (1968)</strong>. <em>&quot;A formal basis for the heuristic determination of minimum cost paths.&quot;</em><br><strong>IEEE Transactions on Systems Science and Cybernetics</strong>, 4(2), pp. 100–107.<br> DOI: <a href="https://doi.org/10.1109/TSSC.1968.300136" target="_blank" rel="noreferrer">10.1109/TSSC.1968.300136</a> <em>(A* Search)</em></li><li><strong>Deutsch, D. N. (1976)</strong>. <em>&quot;A &#39;dogleg&#39; channel router.&quot;</em><br><strong>Proceedings of the 13th Design Automation Conference (DAC &#39;76)</strong>, pp. 425–433.<br> DOI: <a href="https://doi.org/10.1145/800263.810688" target="_blank" rel="noreferrer">10.1145/800263.810688</a></li></ul><hr><h2 id="modelscript-architectural-rationale" tabindex="-1">ModelScript Architectural Rationale <a class="header-anchor" href="#modelscript-architectural-rationale" aria-label="Permalink to &quot;ModelScript Architectural Rationale&quot;">​</a></h2><p>Physical engineering schematics (such as Modelica connection diagrams, SysML v2 Internal Block Diagrams, and hydraulic/piping schematics) require strict geometric conventions:</p><ul><li><strong>Orthogonal Edges</strong>: Connections must run strictly along horizontal and vertical channels with clean $90^\\circ$ bends.</li><li><strong>Port-Constraint Preservation</strong>: High-degree engineering components have physical boundary pins (e.g. electrical resistors have pins $p$ and $n$ on opposite faces; hydraulic valves have ports $A$, $B$, $P$, $T$). Layout engines must place connection points on explicit component boundaries rather than abstract node centers.</li><li><strong>Zero-Obstacle Penetration</strong>: Wires must never traverse component bounding boxes.</li><li><strong>Bus Disambiguation</strong>: Multi-variable connections between blocks must not collapse onto identical collinear segments.</li></ul><p>ModelScript implements the <strong>Topology-Shape-Metrics (TSM)</strong> pipeline augmented with a <strong>Global Port ILP Solver</strong> and <strong>Dogleg Channel Router</strong> natively in the browser and CLI.</p><hr><h2 id="three-phase-layout-routing-architecture" tabindex="-1">Three-Phase Layout &amp; Routing Architecture <a class="header-anchor" href="#three-phase-layout-routing-architecture" aria-label="Permalink to &quot;Three-Phase Layout &amp; Routing Architecture&quot;">​</a></h2>',18)),s(o,{code:"flowchart%20TD%0A%20%20%20%20INPUT%5B%22Modelica%20Connects%20%2F%20SysML%20v2%20Item%20Flows%22%5D%20--%3E%20PORT_OPT%5B%22Phase%201%3A%20Port%20Constraint%20Optimization%3Cbr%2F%3E(Face%20Assignment%20%26%20Cross-Free%20Ordering)%22%5D%0A%20%20%20%20PORT_OPT%20--%3E%20TSM%5B%22Phase%202%3A%20Topology-Shape-Metrics%20(TSM)%3Cbr%2F%3E1.%20Planarization%20%26%20Crossing%20Minimization%3Cbr%2F%3E2.%20Orthogonal%20Shape%20via%20Network%20Flow%3Cbr%2F%3E3.%20Metric%20Coordinate%20Compaction%22%5D%0A%20%20%20%20TSM%20--%3E%20ROUTER%5B%22Phase%203%3A%20Orthogonal%20Channel%20Routing%3Cbr%2F%3E1.%20Normal%20Outward%20Port%20Stubs%3Cbr%2F%3E2.%20Obstacle-Avoiding%20Bend-Penalized%20A*%3Cbr%2F%3E3.%20Staggered%20Parallel%20Dogleg%20Offsets%22%5D%0A%20%20%20%20ROUTER%20--%3E%20RENDER%5B%22SVG%20%2F%20Canvas%20%2F%20Web%20IDE%20Viewport%22%5D%0A"}),e[1]||(e[1]=t('<h3 id="_1-port-constraint-continuous-alignment-solver" tabindex="-1">1. Port Constraint &amp; Continuous Alignment Solver <a class="header-anchor" href="#_1-port-constraint-continuous-alignment-solver" aria-label="Permalink to &quot;1. Port Constraint &amp; Continuous Alignment Solver&quot;">​</a></h3><p>Resolves port assignment along component perimeters ($x, y \\in \\partial \\text{Node}$):</p><ul><li><strong>Discrete Face Selection</strong>: Assigns ports to Cardinal sides (<code>top</code>, <code>bottom</code>, <code>left</code>, <code>right</code>) minimizing Manhattan connection distance: $$\\min \\sum_{e = (u_i, v_j) \\in E} | \\mathbf{p}(u_i) - \\mathbf{p}(v_j) |_1$$</li><li><strong>Causality Biasing</strong>: Automatically places <code>input</code> ports on the left face and <code>output</code> ports on the right face for signal-flow blocks.</li><li><strong>Collinear Port Snapping</strong>: Enforces 0-bend straight lines whenever two connected ports are horizontally or vertically aligned within a configurable tolerance <code>straightTolerance</code>.</li></ul><h3 id="_2-topology-shape-metrics-tsm-engine" tabindex="-1">2. Topology-Shape-Metrics (TSM) Engine <a class="header-anchor" href="#_2-topology-shape-metrics-tsm-engine" aria-label="Permalink to &quot;2. Topology-Shape-Metrics (TSM) Engine&quot;">​</a></h3><p>Extends Tamassia&#39;s Kandinsky model for high-degree engineering vertices:</p><ol><li><strong>Planarization</strong>: Replaces unavoidable edge crossings with dummy vertices of degree 4.</li><li><strong>Orthogonalization (Minimum Bend Flow)</strong>: Formulates bend minimization as a minimum-cost network flow problem over the dual graph, assigning angles $\\alpha \\in {90^\\circ, 180^\\circ, 270^\\circ, 360^\\circ}$ to faces.</li><li><strong>Compaction</strong>: Solves two independent 1D longest path problems on horizontal and vertical constraint DAGs to compute minimal integer grid coordinates.</li></ol><h3 id="_3-obstacle-avoiding-dogleg-channel-router" tabindex="-1">3. Obstacle-Avoiding Dogleg Channel Router <a class="header-anchor" href="#_3-obstacle-avoiding-dogleg-channel-router" aria-label="Permalink to &quot;3. Obstacle-Avoiding Dogleg Channel Router&quot;">​</a></h3><p>Renders clean multi-segment connection polylines:</p><ul><li><strong>Perpendicular Port Stubs</strong>: Edge paths extend outward along the port normal vector by a distance <code>stubLength</code> before turning.</li><li><strong>A* Grid Search with Bend Penalty</strong>: Avoids component AABB bounding boxes using fast <code>segmentIntersectsRect</code> intersection tests while penalizing unnecessary turns: $$\\text{Cost}(p \\to q) = \\text{dist}(p, q) + \\lambda_{\\text{bend}} \\cdot [\\text{isTurn}(p, q)]$$</li><li><strong>Staggered Parallel Channels</strong>: Multi-wire bus connections share a common corridor but are offset by <code>parallelIndex * channelSpacing</code>, preventing overlapping lines.</li></ul><h3 id="_4-specialized-engineering-diagram-layouts" tabindex="-1">4. Specialized Engineering Diagram Layouts <a class="header-anchor" href="#_4-specialized-engineering-diagram-layouts" aria-label="Permalink to &quot;4. Specialized Engineering Diagram Layouts&quot;">​</a></h3><p>Beyond acausal block schematics, ModelScript provides domain-specific geometric layout engines tailored to safety, behavioral, and power-systems engineering notations:</p><ol><li><strong>Fault Tree Gate Hierarchy Layout (<code>fault-tree.ts</code> / <code>fault-tree-layout.ts</code>)</strong>: <ul><li><code>synthesizeFaultTreeDiagram</code> transforms Minimal Cut Sets ($\\text{MCS} = { C_1, \\dots, C_m }$) into four-tier standardized Fault Tree Analysis (FTA) diagrams: <ul><li><strong>Tier 1 ($y = 40$)</strong>: Top Hazard Event rect node centered at $x_{\\text{center}} = W / 2$.</li><li><strong>Tier 2 ($y = 160$)</strong>: Root Boolean <code>OR</code> gate (<code>createGateMarkup(&quot;OR&quot;)</code> SVG bezier shield) aggregating cut-set branches.</li><li><strong>Tier 3 ($y = 280$)</strong>: Intermediate <code>AND</code> gates for multi-point failure cut sets ($\\text{order} &gt; 1$), while order-1 Single Points of Failure (SPOFs) route directly in high-visibility crimson (<code>#dc2626</code>) to basic events.</li><li><strong>Tier 4 ($y = 420$)</strong>: Deduplicated circular Basic Event leaf nodes (<code>basicEventNodesMap</code>) distributed symmetrically across the horizontal span.</li></ul></li></ul></li><li><strong>UML / SysML v2 Sequence &amp; Activity Swimlane Layouts (<code>sequence-layout.ts</code>, <code>swimlane-layout.ts</code>)</strong>: <ul><li><strong>Dual-Axis Sequence Layout (<code>computeSequenceLayout</code> / <code>applySequenceLayout</code>)</strong>: Orders participant lifelines left-to-right ($x_i = x_{\\text{left}} + i \\cdot \\Delta x_{\\text{lifeline}} + W_{\\text{hdr}}/2$), renders dashed vertical lifeline stems (<code>__seq_stem_*</code>), and stacks temporal messages top-to-bottom ($y_{k+1} = y_k + \\Delta y_{\\text{msg}}$) with distinct styling for synchronous (<code>sync</code>), asynchronous (<code>async</code>), dashed <code>reply</code>, and self-loop (<code>isSelf</code>, $1.5\\times$ vertical spacing) messages.</li><li><strong>2D Activity Swimlane Partitioning (<code>applySwimlaneLayout</code>)</strong>: Groups SysML v2 action nodes into vertical or horizontal allocation partitions (<code>SwimlanePartition</code>), sizing uniform lane containers (<code>swimlane_&lt;id&gt;</code>) to the maximum member stack height and routing cross-lane object/control flows via <code>port-orthogonal-astar</code>.</li></ul></li><li><strong>PSCAD Power-System Single-Line Diagram (SLD) Busbar/Feeder Orthogonal Routing (<code>pscad-diagram-builder.ts</code> / <code>pscad-sld-builder.ts</code>)</strong>: <ul><li><code>buildPscadDiagram</code> renders <code>.pscx</code>/<code>.pslx</code> electromagnetic transient models into IEEE-standard Single-Line Diagrams with voltage-coded busbar glyphs ($\\ge 200\\text{ kV}$ red <code>#ff5252</code>, $\\ge 69\\text{ kV}$ amber <code>#ffab40</code>, $&lt; 69\\text{ kV}$ cyan <code>#40c4ff</code>), specialized IEEE apparatus vector glyphs (<code>transformerGlyph</code>, <code>generatorGlyph</code>, <code>inverterIbrGlyph</code>, <code>breakerGlyph</code>, <code>surgeArresterGlyph</code>, <code>faultGlyph</code>, <code>converterBridgeGlyph</code>), solder-dot wire T-junctions, and orthogonal feeder routing.</li></ul></li></ol><h3 id="_5-semantic-visual-diffing-collaborative-presence" tabindex="-1">5. Semantic Visual Diffing &amp; Collaborative Presence <a class="header-anchor" href="#_5-semantic-visual-diffing-collaborative-presence" aria-label="Permalink to &quot;5. Semantic Visual Diffing &amp; Collaborative Presence&quot;">​</a></h3><ol><li><strong>AST-Aware Structural Graph Diffing &amp; Mental-Map Stabilization (<code>visual-diff-graph.ts</code>, <code>visual-diff-renderer.ts</code> / <code>visual-diff.ts</code>)</strong>: <ul><li><code>buildVisualDiffGraph</code> computes a semantic delta between <code>Base</code> and <code>Head</code> diagram revisions, classifying nodes and edges into <code>added</code>, <code>deleted</code>, <code>modified</code>, and <code>unchanged</code> states (<code>DiffStatus</code>).</li><li><strong>Breaking Interface Detection</strong>: Inspects property and port changes (<code>diffProperties</code>) against architectural breaking keys (<code>direction</code>, <code>isAbstract</code>, <code>typeName</code>, <code>multiplicity</code>, <code>causality</code>, <code>variability</code>, <code>flowDirection</code>) and flags deleted components or port-count mutations as <code>MODIFIED (BREAKING)</code>.</li><li><strong>Anchor-Preserving Layout Stabilization (<code>computeIncrementalStabilization</code>)</strong>: Locks <code>Base</code> node coordinates as immutable spatial anchors while iteratively relaxing newly added/modified <code>Head</code> nodes to eliminate bounding-box overlaps without destroying the reviewer&#39;s spatial mental map.</li></ul></li><li><strong>CRDT / WebSocket Cursor, Selection Lock &amp; Spatial Delta Synchronization (<code>collab-manager.ts</code>)</strong>: <ul><li><code>CollabManager</code> coordinates real-time multi-user diagramming over WebSocket and VS Code Live Share transports: <ul><li><strong>60 FPS Spatial Delta Streaming (<code>broadcastSpatialDelta</code>)</strong>: Streams live component drag transformations (<code>PlacementItem</code>) with Last-Write-Wins (<code>LWW</code>) timestamp conflict resolution (<code>d.timestamp &gt;= existing.timestamp</code>).</li><li><strong>Component Selection Locks (<code>SelectionLock</code>)</strong>: Broadcasts per-peer component locks with distinct peer colors and automatic stale-peer heartbeat eviction (<code>purgeStalePeers</code>).</li><li><strong>Anchored Visual Review Comments (<code>DiagramComment</code>)</strong>: Synchronizes spatially pinned sticky-note threads (<code>addComment</code>, <code>resolveComment</code>) directly on the schematic canvas.</li></ul></li></ul></li></ol><hr><h2 id="upstream-downstream-integration" tabindex="-1">Upstream &amp; Downstream Integration <a class="header-anchor" href="#upstream-downstream-integration" aria-label="Permalink to &quot;Upstream &amp; Downstream Integration&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Pipeline Component</th><th style="text-align:left;">Upstream Dependencies</th><th style="text-align:left;">Downstream Consumers</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>PortIlpSolver</strong></td><td style="text-align:left;"><code>SymbolIndex</code> connector ports, <code>Annotation</code> constraints</td><td style="text-align:left;">Port placement in <code>TsmLayoutEngine</code></td></tr><tr><td style="text-align:left;"><strong>TsmLayoutEngine</strong></td><td style="text-align:left;">Polyglot connect graphs (Modelica, SysML v2)</td><td style="text-align:left;">Node bounding box placement, routing channels</td></tr><tr><td style="text-align:left;"><strong>PortRouter</strong></td><td style="text-align:left;">Component layout coordinates, Port locations</td><td style="text-align:left;">SVG polyline rendering, interactive 3D/2D IDE canvas</td></tr><tr><td style="text-align:left;"><strong>FaultTree / Sequence / Swimlane</strong></td><td style="text-align:left;">Safety MCS sets, SysML v2 interactions &amp; activities</td><td style="text-align:left;">X6 WebIDE canvas, headless SVG &amp; PDF documentation export</td></tr><tr><td style="text-align:left;"><strong>PscadDiagramBuilder</strong></td><td style="text-align:left;">PSCAD <code>.pscx</code> / <code>.pslx</code> AST &amp; bus/feeder netlists</td><td style="text-align:left;">Power-system SLD viewer, EMT fault &amp; breaker state overlays</td></tr><tr><td style="text-align:left;"><strong>VisualDiffGraph &amp; CollabManager</strong></td><td style="text-align:left;">Git Base/Head ASTs, WebSocket / Live Share peer streams</td><td style="text-align:left;">PR visual diff bundles (<code>html-diff-bundle.ts</code>), multi-user IDE</td></tr></tbody></table>',17))])}const f=a(l,[["render",c]]);export{b as __pageData,f as default};
